config({ path: ['/home/electronica-care/ezy-prep/exam/app/.env.local'], quiet: true })
const { prisma } = await import('/home/electronica-care/ezy-prep/exam/app/src/lib/prisma.ts')
const { toErrorResponse, withRetry } = await import('/home/electronica-care/ezy-prep/exam/app/src/lib/errors.ts')
const access = await import('/home/electronica-care/ezy-prep/exam/app/src/server/access.ts')

async function show(label: string, f: () => Promise<unknown>) {
  try {
    await f()
    console.log(label, 'no error')
  } catch (e) {
    const r = toErrorResponse(e)
    console.log(label, r.status, await r.text())
  }
}

