await show('withRetry 40001', () => withRetry(async () => { calls++; return prisma.$executeRawUnsafe(`do $$ begin raise exception using errcode = '40001'; end $$`) }))
console.log('retry calls', calls)
const caller = await access.loadCaller('00000000-0000-4000-8000-000000000000')
console.log('caller', JSON.stringify(caller))
await show('lease malformed', () => access.requireLeaseAccess(caller, 'not-a-uuid', ['manager']))
